<?php defined('BASEPATH') or exit('No direct script access allowed'); init_head(); $preProject=(int)$this->input->get('project_id'); $preClient=0; foreach($projects as $pp){if((int)$pp['id']===$preProject){$preClient=(int)$pp['clientid'];break;}} ?>
<div id="wrapper"><?php $this->load->view('admin/_nav'); ?><div class="content"><div class="panel_s"><div class="panel-body"><div class="tw-flex tw-justify-between tw-items-center"><h4><i class="fa fa-cubes"></i> <?= _l('cabinet_maker'); ?></h4><div class="cm-toolbar"><button class="btn btn-default" data-toggle="modal" data-target="#cmImportDesigns"><i class="fa fa-upload"></i> <?= _l('cabinet_maker_import'); ?></button><a class="btn btn-default" href="<?= admin_url('cabinet_maker/sample_designs'); ?>"><i class="fa fa-download"></i> <?= _l('cabinet_maker_sample_header'); ?></a><button class="btn btn-default" onclick="location.reload()"><i class="fa fa-refresh"></i> <?= _l('cabinet_maker_reload'); ?></button><?php if(cabinet_maker_can('create')){ ?><button class="btn btn-primary" data-toggle="modal" data-target="#newDesign"><i class="fa fa-plus"></i> <?= _l('cabinet_maker_new_design'); ?></button><?php } ?></div></div><hr>
