<div class="modal fade" id="newDesign"><div class="modal-dialog"><div class="modal-content"><?= form_open(admin_url('cabinet_maker')); ?><div class="modal-header"><h4><?= _l('cabinet_maker_new_design'); ?></h4></div><div class="modal-body"><?= render_input('name','name','','text',['required'=>true]); ?><div class="form-group"><label><?= _l('client'); ?></label><select name="client_id" id="cmClient" class="selectpicker" data-live-search="true" data-width="100%"><option value=""></option><?php foreach($clients as $c){ ?><option value="<?= $c['userid']; ?>" <?= $preClient===(int)$c['userid']?'selected':''; ?>><?= html_escape($c['company']); ?></option><?php } ?></select></div><div class="form-group"><label><?= _l('project'); ?></label><select name="project_id" id="cmProject" class="selectpicker" data-live-search="true" data-width="100%"><option value=""></option><?php foreach($projects as $p){ ?><option value="<?= $p['id']; ?>" data-client="<?= $p['clientid']; ?>" <?= $preProject===(int)$p['id']?'selected':''; ?>><?= html_escape($p['name']); ?></option><?php } ?></select></div><div class="row"><div class="col-md-4"><?= render_input('room_width','cabinet_maker_room_width',120,'number',['step'=>'.125']); ?></div><div class="col-md-4"><?= render_input('room_length','cabinet_maker_room_length',120,'number',['step'=>'.125']); ?></div><div class="col-md-4"><?= render_input('room_height','cabinet_maker_room_height',96,'number',['step'=>'.125']); ?></div></div></div><div class="modal-footer"><button class="btn btn-primary"><?= _l('create'); ?></button></div><?= form_close(); ?></div></div></div>
<script>document.addEventListener('DOMContentLoaded',function(){var c=document.getElementById('cmClient'),p=document.getElementById('cmProject');if(c&&p)c.addEventListener('change',function(){Array.from(p.options).forEach(function(o){o.hidden=!!c.value&&o.dataset.client&&o.dataset.client!==c.value;});$(p).selectpicker('refresh');});});</script><?php init_tail(); ?>
